        return [c for c in p.split('/') if c not in ('', '.')]

    def join(base, comp):
        if base == '/':
            return '/' + comp
        return base + '/' + comp

    def parent(base):
        if base == '/':
            return '/'
        idx = base.rfind('/')
        if idx <= 0:
            return '/'
        return base[:idx]

    if path.startswith('/'):
